create function public.api_session_valid(p_user uuid,p_session uuid) returns boolean language sql set search_path='' as $$select exists(select 1 from auth.sessions s join public.profiles p on p.id=s.user_id where s.id=p_session and s.user_id=p_user and p.active and (s.not_after is null or s.not_after>now()))$$;
create function public.api_revoke_sessions(p_user uuid) returns void language sql set search_path='' as $$delete from auth.sessions where user_id=p_user$$;
create function public.api_submit_review(p_id uuid,p_actor uuid,p_revision int) returns public.exams language plpgsql set search_path='' as $$declare e public.exams;begin select * into e from public.exams where id=p_id for update;if e.id is null or (e.owner_id<>p_actor and not exists(select 1 from public.profiles where id=p_actor and role='admin' and active)) then raise exception '无权限';end if;if e.revision<>p_revision then raise exception 'CONFLICT:试卷已修改，请重新载入';end if;if e.status not in ('draft','returned') then raise exception '当前状态不能提交';end if;update public.exams set status='pending',updated_at=now() where id=p_id returning * into e;return e;end$$;
create function public.api_transition_exam(p_id uuid,p_actor uuid,p_action text,p_reason text,p_revision int) returns public.exams language plpgsql set search_path='' as $$declare e public.exams;begin select * into e from public.exams where id=p_id for update;if e.id is null then raise exception '试卷不存在';end if;if e.revision<>p_revision then raise exception 'CONFLICT:审核期间试卷已修改，请重新检查';end if;return public.api_review_exam(p_id,p_actor,p_action,p_reason);end$$;
alter table public.profiles add column last_login_at timestamptz;
revoke all on function public.api_session_valid(uuid,uuid),public.api_revoke_sessions(uuid),public.api_submit_review(uuid,uuid,int),public.api_transition_exam(uuid,uuid,text,text,int) from public,anon,authenticated;
grant execute on function public.api_session_valid(uuid,uuid),public.api_revoke_sessions(uuid),public.api_submit_review(uuid,uuid,int),public.api_transition_exam(uuid,uuid,text,text,int) to service_role;
